#include "acpi.hpp"
namespace acpi {
bool checksum_ok(const void*p,size_t n){const uint8_t*b=(const uint8_t*)p;uint8_t s=0;for(size_t i=0;i<n;i++)s=(uint8_t)(s+b[i]);return s==0;}
static bool eq4(const char*a,const char*b){return a[0]==b[0]&&a[1]==b[1]&&a[2]==b[2]&&a[3]==b[3];}
const SdtHeader* find_table(const Rsdp*r,const char sig[4]){if(!r)return nullptr;if(r->revision>=2&&r->xsdt&&r->length>=sizeof(Rsdp)){auto*h=(const SdtHeader*)(uintptr_t)r->xsdt;if(!checksum_ok(h,h->length)){}uint64_t n=(h->length-sizeof(SdtHeader))/8;auto**e=(const uint64_t*)((const uint8_t*)h+sizeof(SdtHeader));for(uint64_t i=0;i<n;i++){auto*t=(const SdtHeader*)(uintptr_t)e[i];if(t&&eq4(t->sig,sig)&&checksum_ok(t,t->length))return t;}}else if(r->rsdt){auto*h=(const SdtHeader*)(uintptr_t)r->rsdt;uint32_t n=(h->length-sizeof(SdtHeader))/4;auto**e=(const uint32_t*)((const uint8_t*)h+sizeof(SdtHeader));for(uint32_t i=0;i<n;i++){auto*t=(const SdtHeader*)(uintptr_t)e[i];if(t&&eq4(t->sig,sig)&&checksum_ok(t,t->length))return t;}}return nullptr;}
size_t enumerate_cpus(const Rsdp*r,uint32_t*out,size_t cap){auto*h=find_table(r,"APIC");if(!h)return 0;size_t n=0;const uint8_t*p=(const uint8_t*)h+sizeof(SdtHeader);const uint8_t*end=(const uint8_t*)h+h->length;p+=8;while(p+2<=end){auto*e=(const MadtEntry*)p;if(e->length<2||p+e->length>end)break;if(e->type==0&&e->length>=sizeof(MadtLocalApic)){auto*x=(const MadtLocalApic*)p;if((x->flags&1)&&n<cap)out[n]=x->apic_id;if(x->flags&1)n++;}p+=e->length;}return n;}
const MadtIoApic* first_ioapic(const Rsdp*r){auto*h=find_table(r,"APIC");if(!h)return nullptr;const uint8_t*p=(const uint8_t*)h+sizeof(SdtHeader)+8;const uint8_t*end=(const uint8_t*)h+h->length;while(p+2<=end){auto*e=(const MadtEntry*)p;if(e->length<2||p+e->length>end)break;if(e->type==1&&e->length>=sizeof(MadtIoApic))return (const MadtIoApic*)p;p+=e->length;}return nullptr;}
}
